import { Controller, Get, Post, Put, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '급여 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const RESIDENT_NO_PATTERN = /^\d{6}-?\d{7}$/;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
// 가정: 일용직 급여 등록 시 마감 상태 초기값은 '신청'
const INITIAL_CLOSING_STATUS = '신청';
const CLOSED_STATUS = '마감';
// 가정: 주민등록번호 암호화 키는 DB 세션 설정(app.resident_key)에서 읽는다 (코드·DB 데이터와 분리)
const RESIDENT_KEY_SETTING = 'app.resident_key';

function fail(message: string): never {
  throw new ApiError(400, 'VALIDATION_FAILED', message);
}

function requiredText(value: unknown, label: string, max: number): string {
  if (typeof value !== 'string' || value.trim() === '') {
    fail(label + '을(를) 입력하세요.');
  }
  const trimmed = (value as string).trim();
  if (trimmed.length > max) {
    fail(label + '은(는) ' + max + '자 이하로 입력하세요.');
  }
  return trimmed;
}

function optionalText(value: unknown): string | null {
  if (typeof value !== 'string' || value.trim() === '') {
    return null;
  }
  return value.trim();
}

function numberOf(value: unknown, label: string): number {
  if (value === null || value === undefined || value === '' || typeof value === 'boolean') {
    fail(label + '을(를) 입력하세요.');
  }
  const n = Number(value);
  if (!Number.isFinite(n) || n < 0) {
    fail(label + '은(는) 0 이상의 숫자여야 합니다.');
  }
  return n;
}

function integerOf(value: unknown, label: string): number {
  const n = numberOf(value, label);
  if (!Number.isInteger(n)) {
    fail(label + '은(는) 정수여야 합니다.');
  }
  return n;
}

function dateOf(value: unknown, label: string): string {
  if (typeof value !== 'string' || !DATE_PATTERN.test(value)) {
    fail(label + '은(는) YYYY-MM-DD 형식이어야 합니다.');
  }
  return value as string;
}

function pagingOf(query: Record<string, unknown>): { page: number; size: number } {
  const rawPage = query['page'];
  const rawSize = query['size'];
  let page = 0;
  let size = DEFAULT_SIZE;
  if (rawPage !== undefined && rawPage !== null && rawPage !== '') {
    page = integerOf(rawPage, '쪽 번호');
  }
  if (rawSize !== undefined && rawSize !== null && rawSize !== '') {
    size = integerOf(rawSize, '쪽 크기');
    if (size < 1) {
      fail('쪽 크기는 1 이상이어야 합니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
  }
  return { page, size };
}

@Controller('api/v1')
export class FnSfr02108Controller {
  @Post('/daily-workers')
  @HttpCode(200)
  async createDailyWorker(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const workerName = requiredText(data['workerName'], '성명', 100);
    const residentNo = data['residentNo'];
    if (typeof residentNo !== 'string' || residentNo.trim() === '') {
      fail('주민등록번호를 입력하세요.');
    }
    if (!RESIDENT_NO_PATTERN.test((residentNo as string).trim())) {
      throw new ApiError(422, 'INVALID_RESIDENT_NO', '주민등록번호 형식이 올바르지 않습니다.');
    }
    const residentDigits = (residentNo as string).trim().replace('-', '');
    return transaction(async (db) => {
      const rows = await db.query(
        `INSERT INTO daily_worker (worker_name, resident_no_enc, created_at, updated_at)
         VALUES (:workerName, encode(pgp_sym_encrypt(:residentNo, current_setting(:keySetting)), 'base64'), now(), now())
         RETURNING daily_worker_id AS "dailyWorkerId"`,
        { workerName, residentNo: residentDigits, keySetting: RESIDENT_KEY_SETTING },
      );
      return { dailyWorkerId: Number(rows[0].dailyWorkerId) };
    });
  }

  @Get('/daily-workers')
  async listDailyWorkers(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const workerName = optionalText(query['workerName']);
    const { page, size } = pagingOf(query);
    return transaction(async (db) => {
      const params = { workerName };
      const counts = await db.query(
        `SELECT COUNT(*) AS "total"
         FROM daily_worker
         WHERE (CAST(:workerName AS text) IS NULL OR strpos(lower(worker_name), lower(CAST(:workerName AS text))) > 0)`,
        params,
      );
      const items = await db.query(
        `SELECT daily_worker_id AS "dailyWorkerId", worker_name AS "workerName"
         FROM daily_worker
         WHERE (CAST(:workerName AS text) IS NULL OR strpos(lower(worker_name), lower(CAST(:workerName AS text))) > 0)
         ORDER BY daily_worker_id DESC
         LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { workerName, size, offset: page * size },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/daily-payrolls')
  @HttpCode(200)
  async createDailyPayroll(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const dailyWorkerId = integerOf(data['dailyWorkerId'], '일용직 사원');
    const payDate = dateOf(data['payDate'], '급여 지급일');
    const workDays = integerOf(data['workDays'], '근무일수');
    const payAmount = numberOf(data['payAmount'], '지급 금액');
    const rawTax = data['withholdingTax'];
    const hasTax = rawTax !== undefined && rawTax !== null && rawTax !== '';
    const withholdingTax = hasTax ? numberOf(rawTax, '원천징수세액') : null;
    return transaction(async (db) => {
      const workers = await db.query(
        `SELECT daily_worker_id AS "dailyWorkerId" FROM daily_worker WHERE daily_worker_id = CAST(:dailyWorkerId AS bigint)`,
        { dailyWorkerId },
      );
      if (workers.length === 0) {
        throw new ApiError(404, 'DAILY_WORKER_NOT_FOUND', '일용직 사원을 찾을 수 없습니다.');
      }
      const existing = await db.query(
        `SELECT closing_status AS "closingStatus"
         FROM daily_payroll
         WHERE daily_worker_id = CAST(:dailyWorkerId AS bigint) AND pay_date = CAST(:payDate AS date)`,
        { dailyWorkerId, payDate },
      );
      if (existing.length > 0) {
        if (existing[0].closingStatus === CLOSED_STATUS) {
          throw new ApiError(409, 'DAILY_PAYROLL_CLOSED', '마감된 급여 기간에는 등록할 수 없습니다.');
        }
        throw new ApiError(409, 'INVALID_STATE', '같은 지급일의 급여정보가 이미 등록되어 있습니다.');
      }
      const rows = await db.query(
        `INSERT INTO daily_payroll
           (daily_worker_id, pay_date, work_days, pay_amount, withholding_tax, closing_status, created_at, updated_at)
         VALUES
           (CAST(:dailyWorkerId AS bigint), CAST(:payDate AS date), CAST(:workDays AS integer),
            CAST(:payAmount AS numeric), CAST(:withholdingTax AS numeric), :closingStatus, now(), now())
         RETURNING daily_payroll_id AS "dailyPayrollId"`,
        { dailyWorkerId, payDate, workDays, payAmount, withholdingTax, closingStatus: INITIAL_CLOSING_STATUS },
      );
      return { dailyPayrollId: Number(rows[0].dailyPayrollId) };
    });
  }

  @Put('/daily-payrolls/:dailyPayrollId')
  async updateDailyPayroll(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const dailyPayrollId = integerOf(req.params['dailyPayrollId'], '일용직 급여 ID');
    const data = checks.inputOf(req.body);
    const payDate = dateOf(data['payDate'], '급여 지급일');
    const workDays = integerOf(data['workDays'], '근무일수');
    const payAmount = numberOf(data['payAmount'], '지급 금액');
    const rawTax = data['withholdingTax'];
    const hasTax = rawTax !== undefined && rawTax !== null && rawTax !== '';
    const withholdingTax = hasTax ? numberOf(rawTax, '원천징수세액') : null;
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT closing_status AS "closingStatus", daily_worker_id AS "dailyWorkerId"
         FROM daily_payroll
         WHERE daily_payroll_id = CAST(:dailyPayrollId AS bigint)`,
        { dailyPayrollId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'DAILY_PAYROLL_NOT_FOUND', '일용직 급여정보를 찾을 수 없습니다.');
      }
      if (found[0].closingStatus === CLOSED_STATUS) {
        throw new ApiError(409, 'DAILY_PAYROLL_CLOSED', '마감된 급여는 마감취소 없이 수정할 수 없습니다.');
      }
      const clash = await db.query(
        `SELECT daily_payroll_id AS "dailyPayrollId"
         FROM daily_payroll
         WHERE daily_worker_id = CAST(:dailyWorkerId AS bigint)
           AND pay_date = CAST(:payDate AS date)
           AND daily_payroll_id <> CAST(:dailyPayrollId AS bigint)`,
        { dailyWorkerId: found[0].dailyWorkerId, payDate, dailyPayrollId },
      );
      if (clash.length > 0) {
        throw new ApiError(409, 'INVALID_STATE', '같은 지급일의 급여정보가 이미 등록되어 있습니다.');
      }
      await db.execute(
        `UPDATE daily_payroll
         SET pay_date = CAST(:payDate AS date),
             work_days = CAST(:workDays AS integer),
             pay_amount = CAST(:payAmount AS numeric),
             withholding_tax = CAST(:withholdingTax AS numeric),
             updated_at = now()
         WHERE daily_payroll_id = CAST(:dailyPayrollId AS bigint)`,
        { payDate, workDays, payAmount, withholdingTax, dailyPayrollId },
      );
      return { dailyPayrollId };
    });
  }

  @Get('/daily-payrolls')
  async listDailyPayrolls(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const rawWorker = query['dailyWorkerId'];
    const hasWorker = rawWorker !== undefined && rawWorker !== null && rawWorker !== '';
    const dailyWorkerId = hasWorker ? integerOf(rawWorker, '일용직 사원') : null;
    const rawDate = query['payDate'];
    const hasDate = rawDate !== undefined && rawDate !== null && rawDate !== '';
    const payDate = hasDate ? dateOf(rawDate, '급여 지급일') : null;
    const { page, size } = pagingOf(query);
    return transaction(async (db) => {
      const counts = await db.query(
        `SELECT COUNT(*) AS "total"
         FROM daily_payroll
         WHERE (CAST(:dailyWorkerId AS bigint) IS NULL OR daily_worker_id = CAST(:dailyWorkerId AS bigint))
           AND (CAST(:payDate AS date) IS NULL OR pay_date = CAST(:payDate AS date))`,
        { dailyWorkerId, payDate },
      );
      const items = await db.query(
        `SELECT daily_payroll_id AS "dailyPayrollId",
                daily_worker_id AS "dailyWorkerId",
                to_char(pay_date, 'YYYY-MM-DD') AS "payDate",
                work_days AS "workDays",
                pay_amount AS "payAmount",
                withholding_tax AS "withholdingTax",
                closing_status AS "closingStatus"
         FROM daily_payroll
         WHERE (CAST(:dailyWorkerId AS bigint) IS NULL OR daily_worker_id = CAST(:dailyWorkerId AS bigint))
           AND (CAST(:payDate AS date) IS NULL OR pay_date = CAST(:payDate AS date))
         ORDER BY pay_date DESC, daily_payroll_id DESC
         LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { dailyWorkerId, payDate, size, offset: page * size },
      );
      return {
        items: items.map((r: any) => ({
          ...r,
          payAmount: Number(r.payAmount),
          withholdingTax: r.withholdingTax === null ? null : Number(r.withholdingTax),
        })),
        page,
        size,
        total: Number(counts[0].total),
      };
    });
  }
}

