import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  TextInput,
  NumberInput,
  DateInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;
const CLOSED = '마감';

type DrawerState =
  | { kind: 'worker' }
  | { kind: 'payroll' }
  | { kind: 'edit'; row: Row }
  | { kind: 'detail'; row: Row }
  | null;

function WorkerForm({ role, onDone }: { role: string; onDone: () => void }) {
  const [workerName, setWorkerName] = useState('');
  const [residentNo, setResidentNo] = useState('');
  return (
    <Form
      submit="등록"
      onSubmit={async () => {
        if (String(workerName).trim() === '') throw new Error('성명을 입력하세요.');
        if (String(residentNo).trim() === '') throw new Error('주민등록번호를 입력하세요.');
        await call('POST', '/daily-workers', role, { workerName, residentNo });
        onDone();
      }}
    >
      <Field label="성명" required>
        <TextInput value={workerName} onChange={setWorkerName} />
      </Field>
      <Field label="주민등록번호" required hint="저장 시 암호화됩니다. 예: 900101-1234567">
        <TextInput value={residentNo} onChange={setResidentNo} />
      </Field>
    </Form>
  );
}

function PayrollForm({ role, row, onDone }: { role: string; row?: Row; onDone: () => void }) {
  const editing = row !== undefined;
  const [dailyWorkerId, setDailyWorkerId] = useState<unknown>(row ? row['dailyWorkerId'] : '');
  const [payDate, setPayDate] = useState<unknown>(row ? row['payDate'] : '');
  const [workDays, setWorkDays] = useState<unknown>(row ? row['workDays'] : '');
  const [payAmount, setPayAmount] = useState<unknown>(row ? row['payAmount'] : '');
  const [withholdingTax, setWithholdingTax] = useState<unknown>(row && row['withholdingTax'] !== null ? row['withholdingTax'] : '');
  return (
    <Form
      submit={editing ? '수정' : '등록'}
      onSubmit={async () => {
        if (!editing && (dailyWorkerId === '' || dailyWorkerId === null || dailyWorkerId === undefined)) {
          throw new Error('일용직 사원을 선택하세요.');
        }
        if (!payDate) throw new Error('급여 지급일을 입력하세요.');
        if (workDays === '' || workDays === undefined) throw new Error('근무일수를 입력하세요.');
        if (payAmount === '' || payAmount === undefined) throw new Error('지급 금액을 입력하세요.');
        const body: Row = { payDate, workDays, payAmount, withholdingTax: withholdingTax === '' ? null : withholdingTax };
        if (editing) {
          await call('PUT', '/daily-payrolls/' + String(row!['dailyPayrollId']), role, body);
        } else {
          body['dailyWorkerId'] = dailyWorkerId;
          await call('POST', '/daily-payrolls', role, body);
        }
        onDone();
      }}
    >
      <Field label="일용직 사원" required>
        {editing ? (
          <RefName table="daily_worker" role={role} value={dailyWorkerId} />
        ) : (
          <LookupSelect table="daily_worker" role={role} value={dailyWorkerId} onChange={setDailyWorkerId} />
        )}
      </Field>
      <Field label="급여 지급일" required>
        <DateInput value={payDate} onChange={setPayDate} />
      </Field>
      <Field label="근무일수" required>
        <NumberInput value={workDays} onChange={setWorkDays} />
      </Field>
      <Field label="지급 금액" required>
        <NumberInput value={payAmount} onChange={setPayAmount} />
      </Field>
      <Field label="원천징수세액">
        <NumberInput value={withholdingTax} onChange={setWithholdingTax} />
      </Field>
    </Form>
  );
}

export default function FnSfr02108Page({ role, notify }: PageProps) {
  const [drawer, setDrawer] = useState<DrawerState>(null);

  const [nameInput, setNameInput] = useState('');
  const [nameQuery, setNameQuery] = useState('');
  const [workerPage, setWorkerPage] = useState(0);

  const [filterWorker, setFilterWorker] = useState<unknown>('');
  const [filterDate, setFilterDate] = useState<unknown>('');
  const [appliedWorker, setAppliedWorker] = useState<unknown>('');
  const [appliedDate, setAppliedDate] = useState<unknown>('');
  const [payrollPage, setPayrollPage] = useState(0);

  const workers = useData<Page>(
    () => call<Page>('GET', '/daily-workers', role, undefined, { workerName: nameQuery, page: workerPage, size: SIZE }),
    [role, nameQuery, workerPage],
  );
  const payrolls = useData<Page>(
    () =>
      call<Page>('GET', '/daily-payrolls', role, undefined, {
        dailyWorkerId: appliedWorker,
        payDate: appliedDate,
        page: payrollPage,
        size: SIZE,
      }),
    [role, appliedWorker, appliedDate, payrollPage],
  );

  const done = (message: string) => {
    setDrawer(null);
    notify(message);
    workers.reload();
    payrolls.reload();
  };

  return (
    <div className="bento">
      <section className="box span-3">
        <h2>일용직 사원</h2>
        <Tiles items={[['등록 인원', <Num value={workers.data ? workers.data.total : 0} />]]} />
      </section>
      <section className="box span-3">
        <h2>급여 내역</h2>
        <Tiles items={[['조회 건수', <Num value={payrolls.data ? payrolls.data.total : 0} />]]} />
      </section>

      <section className="box span-8">
        <h2>지급일별 급여</h2>
        <Filters
          onSearch={() => {
            setPayrollPage(0);
            setAppliedWorker(filterWorker);
            setAppliedDate(filterDate);
          }}
          onReset={() => {
            setFilterWorker('');
            setFilterDate('');
            setAppliedWorker('');
            setAppliedDate('');
            setPayrollPage(0);
          }}
        >
          <Field label="일용직 사원">
            <LookupSelect table="daily_worker" role={role} value={filterWorker} onChange={setFilterWorker} />
          </Field>
          <Field label="급여 지급일">
            <DateInput value={filterDate} onChange={setFilterDate} />
          </Field>
        </Filters>
        <Band total={payrolls.data ? payrolls.data.total : undefined}>
          <button type="button" onClick={() => setDrawer({ kind: 'payroll' })}>급여 등록</button>
        </Band>
        {payrolls.error ? <ErrorText text={payrolls.error} /> : null}
        <DataTable
          rows={payrolls.data ? payrolls.data.items : []}
          empty="등록된 급여 내역이 없습니다."
          onRowClick={(row) => setDrawer({ kind: 'detail', row })}
          columns={[
            { key: 'payDate', label: '급여 지급일', render: (r) => <DateText value={r['payDate']} /> },
            { key: 'dailyWorkerId', label: '일용직 사원', render: (r) => <RefName table="daily_worker" role={role} value={r['dailyWorkerId']} /> },
            { key: 'workDays', label: '근무일수', render: (r) => <Num value={r['workDays']} /> },
            { key: 'payAmount', label: '지급 금액', render: (r) => <Num value={r['payAmount']} /> },
            { key: 'withholdingTax', label: '원천징수세액', render: (r) => <Num value={r['withholdingTax']} /> },
            { key: 'closingStatus', label: '마감 상태', render: (r) => <Badge value={r['closingStatus']} /> },
          ]}
        />
        <Pager
          page={payrollPage}
          size={SIZE}
          total={payrolls.data ? payrolls.data.total : 0}
          onPage={setPayrollPage}
        />
      </section>

      <section className="box span-4">
        <h2>사원 목록</h2>
        <Filters
          onSearch={() => {
            setWorkerPage(0);
            setNameQuery(nameInput);
          }}
          onReset={() => {
            setNameInput('');
            setNameQuery('');
            setWorkerPage(0);
          }}
        >
          <Field label="성명">
            <TextInput value={nameInput} onChange={setNameInput} />
          </Field>
        </Filters>
        <Band total={workers.data ? workers.data.total : undefined}>
          <button type="button" onClick={() => setDrawer({ kind: 'worker' })}>사원 등록</button>
        </Band>
        {workers.error ? <ErrorText text={workers.error} /> : null}
        <DataTable
          rows={workers.data ? workers.data.items : []}
          empty="등록된 사원이 없습니다."
          columns={[{ key: 'workerName', label: '성명' }]}
        />
        <Pager
          page={workerPage}
          size={SIZE}
          total={workers.data ? workers.data.total : 0}
          onPage={setWorkerPage}
        />
      </section>

      {drawer && drawer.kind === 'worker' ? (
        <Drawer title="일용직 사원 등록" onClose={() => setDrawer(null)}>
          <WorkerForm role={role} onDone={() => done('일용직 사원을 등록했습니다.')} />
        </Drawer>
      ) : null}

      {drawer && drawer.kind === 'payroll' ? (
        <Drawer title="일용직 급여 등록" onClose={() => setDrawer(null)}>
          <PayrollForm role={role} onDone={() => done('일용직 급여정보를 등록했습니다.')} />
        </Drawer>
      ) : null}

      {drawer && drawer.kind === 'edit' ? (
        <Drawer title="일용직 급여 수정" onClose={() => setDrawer(null)}>
          <PayrollForm role={role} row={drawer.row} onDone={() => done('일용직 급여정보를 수정했습니다.')} />
        </Drawer>
      ) : null}

      {drawer && drawer.kind === 'detail' ? (
        <Drawer title="일용직 급여 상세" onClose={() => setDrawer(null)}>
          <Pairs
            items={[
              ['일용직 사원', <RefName table="daily_worker" role={role} value={drawer.row['dailyWorkerId']} />],
              ['급여 지급일', <DateText value={drawer.row['payDate']} />],
              ['근무일수', <Num value={drawer.row['workDays']} />],
              ['지급 금액', <Num value={drawer.row['payAmount']} />],
              ['원천징수세액', <Num value={drawer.row['withholdingTax']} />],
              ['마감 상태', <Badge value={drawer.row['closingStatus']} />],
            ]}
          />
          {drawer.row['closingStatus'] !== CLOSED ? (
            <button type="button" onClick={() => setDrawer({ kind: 'edit', row: drawer.row })}>수정</button>
          ) : null}
        </Drawer>
      ) : null}
    </div>
  );
}
